using System.Diagnostics.CodeAnalysis;
using System.Text.Json.Serialization;

using idunno.AtProto;
using idunno.AtProto.Labels;
using idunno.AtProto.Repo;
using idunno.Bluesky.Actor;
using idunno.Bluesky.Embed;
using idunno.Bluesky.Record;

namespace idunno.Bluesky.Feed;

/// <summary>
/// A view over a post record generated by a Bluesky feed.
/// </summary>
/// <remarks>
/// <para>See https://docs.bsky.app/docs/api/app-bsky-feed-get-posts</para>
/// <para>See https://github.com/bluesky-social/atproto/blob/main/lexicons/app/bsky/feed/defs.json</para>
/// </remarks>
public sealed record PostView : PostViewBase
{
    [JsonConstructor]
    internal PostView(
        AtUri uri,
        Cid cid,
        ProfileViewBasic author,
        int replyCount,
        int repostCount,
        int likeCount,
        int quoteCount,
        int bookmarkCount,
        ThreadGateView? threadGate,
        DateTimeOffset indexedAt,
        ViewerState? viewer,
        IReadOnlyCollection<Label>? labels,
        EmbeddedView? embed)
    {
        Uri = uri;
        Cid = cid;
        StrongReference = new StrongReference(uri, cid);

        Author = author;

        ReplyCount = replyCount;
        RepostCount = repostCount;
        LikeCount = likeCount;
        QuoteCount = quoteCount;
        BookmarkCount = bookmarkCount;

        ThreadGate = threadGate;

        IndexedAt = indexedAt;

        Viewer = viewer;

        Labels = labels ?? [];

        Embed = embed;
    }

    /// <summary>
    /// The <see cref="AtUri"/> for the post.
    /// </summary>
    [JsonRequired]
    public AtUri Uri { get; init; }

    /// <summary>
    /// The <see cref="Cid">content identifier</see> for the post.
    /// </summary>
    [JsonRequired]
    public Cid Cid { get; init; }

    /// <summary>
    /// A <see cref="StrongReference"/> to the post.
    /// </summary>
    [JsonIgnore]
    public StrongReference StrongReference { get; }

    /// <summary>
    /// A <see cref="ProfileViewBasic"/> of the author of the post.
    /// </summary>
    [JsonRequired]
    public ProfileViewBasic Author { get; init; }

    /// <summary>
    /// Gets the value of the post record.
    /// </summary>
    /// <remarks>
    /// <para>The lexicon declares the record as <c>unknown</c>. Post views hold posts in practice, so the record is read
    /// through the polymorphic <see cref="BlueskyRecord"/> contract to keep feed decoding fast. A record whose <c>$type</c> this
    /// library does not recognize, or that has no <c>$type</c>, is returned as a base <see cref="BlueskyRecord"/> whose
    /// <see cref="AtProto.Repo.AtProtoRecord.ExtensionData"/> holds its properties; its <c>$type</c> is not preserved.</para>
    /// </remarks>
    [JsonInclude]
    [JsonRequired]
    [JsonPropertyName("record")]
    public required BlueskyRecord RecordValue { get; init; }

    /// <summary>
    /// Gets the post record.
    /// </summary>
    /// <exception cref="InvalidOperationException">Thrown when <see cref="RecordValue"/> is not a <see cref="Post"/>.</exception>
    /// <remarks>
    /// <para>Use <see cref="TryGetPost(out Post?)"/> or <see cref="RecordValue"/> to handle a view whose record is not a post.</para>
    /// </remarks>
    [JsonIgnore]
    public Post Record => RecordValue as Post ??
        throw new InvalidOperationException($"The post view record is a '{RecordValue.GetType().Name}', not a '{nameof(Post)}'.");

    /// <summary>
    /// Gets the post record, if <see cref="RecordValue"/> is a <see cref="Post"/>.
    /// </summary>
    /// <param name="post">When this method returns <see langword="true"/>, the post record; otherwise <see langword="null"/>.</param>
    /// <returns><see langword="true"/> if <see cref="RecordValue"/> is a <see cref="Post"/>; otherwise <see langword="false"/>.</returns>
    public bool TryGetPost([NotNullWhen(true)] out Post? post)
    {
        post = RecordValue as Post;
        return post is not null;
    }

    /// <summary>
    /// The number of replies to this post.
    /// </summary>
    [JsonInclude]
    public int ReplyCount { get; init; }

    /// <summary>
    /// The number of times this post has been reposted.
    /// </summary>
    [JsonInclude]
    public int RepostCount { get; init; }

    /// <summary>
    /// The number of likes this post has.
    /// </summary>
    [JsonInclude]
    public int LikeCount { get; init; }

    /// <summary>
    /// The number of quotes this post has.
    /// </summary>
    [JsonInclude]
    public int QuoteCount { get; init; }

    /// <summary>
    /// The number of times the post has been bookmarked.
    /// </summary>
    [JsonInclude]
    public int BookmarkCount { get; init; }

    /// <summary>
    /// The number of times the post has been viewed, if the server supplied it.
    /// </summary>
    /// <remarks>
    /// <para>The server only supplies the view count to the author of the post.</para>
    /// </remarks>
    [JsonInclude]
    public int? ViewCount { get; init; }

    /// <summary>
    /// The date and time the post was indexed at.
    /// </summary>
    [JsonInclude]
    [JsonRequired]
    public DateTimeOffset IndexedAt { get; init; }

    /// <summary>
    /// An optional <see cref="ThreadGate"/> controlling who can reply to a post.
    /// </summary>
    [JsonInclude]
    [JsonPropertyName("threadgate")]
    public ThreadGateView? ThreadGate { get; init; }

    /// <summary>
    /// Metadata about the requesting account's relationship with the subject content.
    /// Only has meaningful content for authenticated requests.
    /// </summary>
    [JsonInclude]
    public ViewerState? Viewer { get; init; }

    /// <summary>
    /// Any labels applied to the post.
    /// </summary>
    /// <remarks>
    /// <para>Entries that the server supplies as <see langword="null"/> are discarded.</para>
    /// </remarks>
    [JsonInclude]
    public IReadOnlyCollection<Label> Labels
    {
        get;
        init => field = NullEntryFilter.WithoutNullEntries(value);
    }

    /// <summary>
    /// Returns a list of label values for labels that appear to have been applied by the actor to themselves, based on the label source and uri.
    /// </summary>
    /// <remarks>
    /// <para>Known Bluesky label values can be found in <see cref="SelfLabelValues"/>.</para>
    /// </remarks>
    [JsonIgnore]
    public IReadOnlyList<string> SelfLabels
    {
        get
        {
            field ??= Labels.Count == 0 ? [] : SelfLabelReader.Read(Labels, Author.Did, Uri.ToString(), matchCid: true, Cid);

            return field;
        }

        private set;
    }

    /// <summary>
    /// An optional <see cref="EmbeddedView" /> for embedded media information.
    /// </summary>
    [JsonInclude]
    public EmbeddedView? Embed { get; init; }
}